function CanonicalRoutedApp(){const[route,setRoute]=useState(resolveCanonicalRoute);useEffect(()=>installVisibleLinkPrefetch(),[]);useEffect(()=>{const sync=()=>setRoute(resolveCanonicalRoute());window.addEventListener('popstate',sync);window.addEventListener('pageshow',sync);return()=>{window.removeEventListener('popstate',sync);window.removeEventListener('pageshow',sync)}},[]);return route.service==='hub'?<HubApp active/>:<UnifiedServiceApp active/>}
function App(){const query=new URLSearchParams(location.search);const ownerTest=query.get('owner_test')==='1';const host=location.hostname.toLowerCase();const technical=isTechnicalHost(host);const callbackState=query.get('state')||'';const knownGoogleState=/^(?:v2|mailg\.v1|mailm\.v1|cloudg\.v1|gsuite\.v2)\./.test(callbackState);const googleReturn=(host==='id.tarasevych.com'||technical)&&knownGoogleState&&(query.has('code')||query.has('error'));const customCallback=googleReturn;const technicalAuthorize=ownerTest&&query.get('tab')==='authorize';const customAuthorize=host==='id.tarasevych.com'&&query.get('tab')==='authorize';const content=customCallback?<OwnerIdentityCallback/>:(customAuthorize||technicalAuthorize)?<OwnerIdentityAuthorize lang={query.get('lang')==='nl'?'nl':'uk'}/>:ownerTest?<OwnerTestApp/>:<CanonicalRoutedApp/>;return <>{!(customCallback||technicalAuthorize||customAuthorize)&&ownerTest&&<CanonicalEnvironmentBanner ownerTest={ownerTest}/>} {content}</>}
export default App;
